{#- dacs-font: one font on every server — Liberation Sans (Arial's letter widths) shipped in the app
    (public/fonts), so a print measures and looks the same on local and live (docs/print-formats.md › Font) -#}
{%- set dacs_base = frappe.utils.get_url() -%}
<style>
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Regular.ttf') format('truetype'); font-weight: normal; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Bold.ttf') format('truetype'); font-weight: bold; font-style: normal; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-Italic.ttf') format('truetype'); font-weight: normal; font-style: italic; }
@font-face { font-family: 'Arial'; src: url('{{ dacs_base }}/assets/erp_dacsinc_custom/fonts/LiberationSans-BoldItalic.ttf') format('truetype'); font-weight: bold; font-style: italic; }
body, body * { font-family: Arial !important; }
</style>
{#- Bulk Payment Receipt — one amount (cheque / transfer / cash) and how it was set off: per customer /
    supplier, its invoices and the amount on each, and the Payment Entry made for that party. -#}
{%- set receive = doc.payment_type == "Receive" -%}
{%- set title = "RECEIPT VOUCHER" if receive else "PAYMENT VOUCHER" -%}
{%- set bank = (doc.bank_amount or doc.total_amount or 0) | float -%}
{%- set cuts = (doc.tds_amount or 0) or (doc.write_off_amount or 0) -%}
{%- set words = frappe.utils.money_in_words(bank, "INR") | replace("INR ", "") | replace(" only.", "") | replace(" Only.", "") -%}
{%- set chip = "DRAFT" if doc.docstatus == 0 else ("CANCELLED" if doc.docstatus == 2 else ("RECEIVED" if receive else "PAID")) -%}
{%- set groups = [] -%}{%- set seen = [] -%}
{%- for r in doc.allocations -%}{%- if r.party not in seen -%}{%- set _ = seen.append(r.party) -%}{%- set _ = groups.append(r.party) -%}{%- endif -%}{%- endfor -%}
{#- the letter head is the PDF page header, so it prints on every page (docs/print-formats.md › Page header) -#}
<div id="header-html" class="hidden-pdf">{% if letter_head and not no_letterhead %}<div class="letter-head">{{ letter_head }}</div>{% endif %}</div>
<div id="footer-html" class="visible-pdf"><p class="text-center small page-number visible-pdf" style="font-size:7.5pt;">Page <span class="page"></span> of <span class="topage"></span></p></div>
<style>
  /* page margins: the page header / footer set them (docs/print-formats.md › Page header) */
  .print-format > .page-break:last-child { page-break-after: auto; }
  /* terms written in the editor carry its "height: 100%" and scroll bars: inside the page box they stretched to the
     page and showed scroll arrows — the text keeps its own height */
  .print-format .ql-editor { height: auto !important; overflow: visible !important; padding: 0 !important; }
  .print-format .ql-editor p { margin: 0 !important; }
  /* letter head: tighter gaps (the Letter Head record is shared); the PDF page header's own 5mm bottom padding
     is the gap under the heading; a format with its own header (no letter head) starts at the header's top */
  .print-format .letter-head > div, .print-format .rn-letterhead > div, .print-format .pr-letterhead > div { margin-bottom: 1px !important; }
  .print-format .letter-head > div > div[style*="border-bottom"], .print-format .rn-letterhead > div > div[style*="border-bottom"],
  .print-format .pr-letterhead > div > div[style*="border-bottom"] { margin-top: 2px !important; }
  html body { padding-bottom: 1mm !important; }
  .bp { font-family: Arial, sans-serif; color: #000; font-size: 8.5pt; }
  .bp-head { position: relative; text-align: center; margin: 2px 0 6px; }
  .bp-title { font-size: 12pt; font-weight: bold; letter-spacing: 1px; }
  .bp-sub { font-size: 8.5pt; line-height: 1.4; }
  .bp-chip { position: absolute; top: 0; right: 0; border: 2px solid #000; padding: 4px 10px; font-weight: bold; font-size: 10px; }
  .bp-box { width: 100%; border-collapse: collapse; border: 1.2px solid #000; table-layout: fixed; }
  .bp-box td { vertical-align: top; padding: 5px 6px; }
  .bp-grid td { padding: 1.5px 0; } .bp-grid .k { font-weight: bold; width: 42%; white-space: nowrap; }
  .bp-amount { margin-top: 6px; border: 1.2px solid #000; background: #f2f2f2; padding: 6px 8px; font-size: 11pt; font-weight: bold; }
  .bp-h { font-weight: bold; margin: 8px 0 2px; font-size: 9pt; }
  .bp-t { width: 100%; border-collapse: collapse; }
  .bp-t th { border: 1px solid #000; background: #f2f2f2; padding: 3px 4px; text-align: left; }
  .bp-t td { border: 1px solid #000; padding: 3px 4px; vertical-align: top; }
  .bp-t .r { text-align: right; white-space: nowrap; }
  .bp-t tr.party td { background: #fafafa; font-weight: bold; }
  .bp-t tr.tot td { font-weight: bold; background: #f2f2f2; }
  .bp-words { border: 1px solid #000; padding: 4px 6px; margin-top: 8px; background: #fafafa; }
  .bp-foot { width: 100%; border-collapse: collapse; border: 1px solid #000; border-top: none; table-layout: fixed; }
  .bp-foot td { vertical-align: top; padding: 5px 6px; }
  .bp-sign { text-align: center; } .bp-sign span { display: inline-block; border-top: 1px solid #000; width: 85%; padding-top: 2px; font-weight: bold; }
</style>
<div class="bp">

  <div class="bp-head">
    <div class="bp-title">{{ title }}</div>
    <div class="bp-sub">No: <strong>{{ doc.name }}</strong> | Date: <strong>{{ frappe.utils.formatdate(doc.posting_date, "dd-MMM-yyyy") }}</strong></div>
    <div class="bp-chip">{{ chip }}</div>
  </div>
  <table class="bp-box"><tr>
    <td style="width:55%;border-right:1.2px solid #000;">
      <div style="font-size:7.5pt;">{{ "Received with thanks from" if receive else "Paid to" }}</div>
      <div style="font-weight:bold;font-size:10pt;">{{ groups | length }} {{ ("customer" if receive else "supplier") ~ ("" if groups | length == 1 else "s") }}, {{ doc.allocations | length }} {{ "invoice" if receive else "bill" }}{{ "" if doc.allocations | length == 1 else "s" }}</div>
      <div style="font-size:8pt;margin-top:2px;">{% for p in groups %}{% set pr = (doc.allocations | selectattr("party", "equalto", p) | list)[0] %}{{ pr.party_name or p }}{% if not loop.last %} · {% endif %}{% endfor %}</div>
    </td>
    <td><table class="bp-grid" style="width:100%;border-collapse:collapse;">
      <tr><td class="k">Mode of Payment</td><td>: {{ doc.mode_of_payment }}</td></tr>
      {% if doc.reference_no %}<tr><td class="k">Cheque / Ref. No.</td><td>: {{ doc.reference_no }}</td></tr>{% endif %}
      {% if doc.reference_date %}<tr><td class="k">Cheque / Ref. Date</td><td>: {{ frappe.utils.formatdate(doc.reference_date) }}</td></tr>{% endif %}
      <tr><td class="k">{{ "Deposited to" if receive else "Paid from" }}</td><td>: {{ (doc.bank_cash_account or "").rsplit(" - ", 1)[0] }}</td></tr>
    </table></td>
  </tr></table>
  <div class="bp-amount">{{ "Amount Received" if receive else "Amount Paid" }}: ₹ {{ frappe.utils.fmt_money(bank) }}
    {%- if doc.bank_charges or cuts %}<span style="font-size:8pt;font-weight:normal;"> (settles ₹ {{ frappe.utils.fmt_money(doc.total_amount or 0) }}{% if doc.bank_charges %} · bank charges {{ frappe.utils.fmt_money(doc.bank_charges) }}{% endif %}{% if doc.tds_amount %} · TDS {{ frappe.utils.fmt_money(doc.tds_amount) }}{% endif %}{% if doc.write_off_amount %} · written off {{ frappe.utils.fmt_money(doc.write_off_amount) }}{% endif %})</span>{% endif %}</div>

  <div class="bp-h">{{ "How it is set off — per customer and invoice" if receive else "How it is set off — per supplier and bill" }}</div>
  <table class="bp-t">
    <thead><tr><th style="width:30%;">{{ "Invoice" if receive else "Bill" }}{% if not receive %} (Supplier Bill No){% endif %}</th><th>Date</th><th class="r">{{ "Invoice" if receive else "Bill" }} Total</th>
      <th class="r">Set off</th>{% if cuts %}<th class="r">TDS</th><th class="r">Write-off</th>{% endif %}<th>Payment Entry</th></tr></thead>
    <tbody>
    {% for p in groups %}
      {%- set rows = doc.allocations | selectattr("party", "equalto", p) | list -%}
      {%- set ns = namespace(sum=0) -%}{%- for r in rows -%}{%- set ns.sum = ns.sum + (r.allocated_amount or 0) -%}{%- endfor -%}
      <tr class="party"><td colspan="3">{{ rows[0].party_name or p }} <span style="font-weight:normal;">({{ p }})</span></td><td class="r">₹ {{ frappe.utils.fmt_money(ns.sum) }}</td>{% if cuts %}<td></td><td></td>{% endif %}<td>{{ rows[0].payment_entry or "" }}</td></tr>
      {% for r in rows %}
      <tr><td>{{ r.reference_name }}{% if r.bill_no %} ({{ r.bill_no }}){% endif %}</td><td>{{ frappe.utils.formatdate(r.posting_date) if r.posting_date else "" }}</td>
        <td class="r">{{ frappe.utils.fmt_money(r.invoice_total or 0) }}</td><td class="r">{{ frappe.utils.fmt_money(r.allocated_amount or 0) }}</td>{% if cuts %}<td class="r">{{ frappe.utils.fmt_money(r.tds_amount) if r.tds_amount else "" }}</td><td class="r">{{ frappe.utils.fmt_money(r.write_off_amount) if r.write_off_amount else "" }}</td>{% endif %}<td></td></tr>
      {% endfor %}
    {% endfor %}
      <tr class="tot"><td colspan="3" class="r">Total</td><td class="r">₹ {{ frappe.utils.fmt_money(doc.allocated_amount or doc.total_amount or 0) }}</td>{% if cuts %}<td class="r">{{ frappe.utils.fmt_money(doc.tds_amount) if doc.tds_amount else "" }}</td><td class="r">{{ frappe.utils.fmt_money(doc.write_off_amount) if doc.write_off_amount else "" }}</td>{% endif %}<td></td></tr>
    </tbody>
  </table>

  <div class="bp-words"><strong>Amount in Words:</strong> <i><strong>Rupees {{ words }} Only</strong></i></div>
  <table class="bp-foot"><tr>
    <td style="width:40%;border-right:1px solid #000;"><div style="font-weight:bold;text-decoration:underline;">Remarks</div><div style="white-space:pre-wrap;">{{ doc.remarks or "—" }}</div>
      {% if receive and doc.mode_of_payment and "cheque" in (doc.mode_of_payment | lower) %}<div style="font-size:7pt;margin-top:4px;">Subject to realisation of the cheque.</div>{% endif %}</td>
    <td class="bp-sign" style="width:30%;border-right:1px solid #000;"><br><br><br><br><span>{{ "Received by" if not receive else "Customer's Signature" }}</span></td>
    <td class="bp-sign" style="width:30%;"><div style="font-weight:bold;">For {{ doc.company }}</div><br><br><br><span>Authorised Signatory</span></td>
  </tr></table>
</div>
